import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { Group, Shape, ExtrudeGeometry, Mesh, PointLight, PlaneGeometry, CanvasTexture } = ctx.THREE;

  const root = new Group();

  // Create local variables for custom theme colors
  const ink = '#16161d';
  const paper = '#e8ecf2';
  const accent = '#ff2a38';
  const surface = '#0b0b10';

  // --- 1. STAGE BACKDROP (Designed for dark, gradient from ink to surface) ---
  // Large backdrop to support depth and ensure contrast (approx 7x6 at z = -2.5)
  const bgWidth = 7.5;
  const bgHeight = 6.5;
  const bgCanvas = document.createElement('canvas');
  bgCanvas.width = 512;
  bgCanvas.height = 512;
  const bgCtx = bgCanvas.getContext('2d');
  const gradient = bgCtx.createLinearGradient(0, 0, 0, 512);
  gradient.addColorStop(0, ink);
  gradient.addColorStop(1, surface);
  bgCtx.fillStyle = gradient;
  bgCtx.fillRect(0, 0, 512, 512);

  const bgTexture = new CanvasTexture(bgCanvas);
  const bgMat = new MeshBasicNodeMaterial({ map: bgTexture });
  const bgMesh = new Mesh(new PlaneGeometry(bgWidth, bgHeight), bgMat);
  bgMesh.position.set(0, 0, -2.5);
  root.add(bgMesh);

  // --- 2. LOCAL LIGHTING (Rim & Highlight) ---
  const localRimLight = new PointLight(accent, 1.4, 4);
  localRimLight.position.set(1.5, 1, 0.5);
  root.add(localRimLight);

  const localKeyLight = new PointLight(paper, 0.8, 4);
  localKeyLight.position.set(-1.5, 1.5, 1);
  root.add(localKeyLight);

  // --- 3. BADGE GROUP (Holds the physical visual representation) ---
  const badgeGroup = new Group();
  root.add(badgeGroup);

  // Create beautiful extruded capsule geometry
  const capWidth = 1.4;
  const capHeight = 0.55;
  const radius = capHeight / 2.05;

  const shape = new Shape();
  shape.absarc(-capWidth/2 + radius, 0, radius, Math.PI/2, Math.PI * 1.5);
  shape.absarc(capWidth/2 - radius, 0, radius, Math.PI * 1.5, Math.PI/2);

  const extrudeSettings = {
    depth: 0.08,
    bevelEnabled: true,
    bevelSegments: 4,
    steps: 1,
    bevelSize: 0.015,
    bevelThickness: 0.015
  };

  const capsuleGeom = new ExtrudeGeometry(shape, extrudeSettings);
  capsuleGeom.center();

  // Capsule Core Material (Machined Metal PBR)
  const coreMat = new MeshStandardNodeMaterial({
    color: surface,
    roughness: 0.45,
    metalness: 0.55,
    clearcoat: 0.2
  });

  const coreMesh = new Mesh(capsuleGeom, coreMat);
  badgeGroup.add(coreMesh);

  // Capsule Edge Rim Light (Accent backer scaled slightly up)
  const rimMat = new MeshStandardNodeMaterial({
    color: accent,
    emissive: accent,
    emissiveIntensity: 1.8,
    roughness: 0.2,
    metalness: 0.1
  });

  const rimMesh = new Mesh(capsuleGeom, rimMat);
  rimMesh.scale.set(1.04, 1.04, 0.9);
  rimMesh.position.z = -0.015;
  badgeGroup.add(rimMesh);

  // --- 4. GLB LOAD AND EMBED (gear-a.glb) ---
  let gearMesh = null;
  let animateTimeline = null;

  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      gearMesh = gltf.scene;

      // Scale and center inside the capsule badge
      gearMesh.scale.set(0.24, 0.24, 0.24);
      gearMesh.position.set(0, 0, 0.06);

      // Apply clean metal finish to GLB components
      gearMesh.traverse((child) => {
        if (child.isMesh) {
          child.material = new MeshStandardNodeMaterial({
            color: paper,
            roughness: 0.25,
            metalness: 0.85,
            clearcoat: 0.1
          });
        }
      });

      badgeGroup.add(gearMesh);

      // Simple elegant rotation idle animation for gears
      animateTimeline = gsap.timeline({ repeat: -1 });
      animateTimeline.to(gearMesh.rotation, {
        z: Math.PI * 2,
        duration: 12,
        ease: 'none'
      });
    }).catch((err) => {
      console.warn('Failed to load asset meshUrl', err);
    });
  }

  // --- 5. ENTRANCE ANIMATION (Weighted Settle) ---
  badgeGroup.scale.set(0.01, 0.01, 0.01);
  gsap.to(badgeGroup.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 1.1,
    ease: 'power4.out',
    delay: 0.1
  });

  // --- 6. INTERACTION & EMIT HANDLERS ---
  let isHovered = false;
  const hoverTl = gsap.timeline({ paused: true });
  // Subtle rise-in of 0.15 scene units on hover
  hoverTl.to(badgeGroup.position, {
    y: 0.15,
    duration: 0.3,
    ease: 'power2.out'
  });

  userDataHandlers(badgeGroup, {
    onPointerOver: () => {
      if (!isHovered) {
        isHovered = true;
        hoverTl.play();
      }
    },
    onPointerOut: () => {
      if (isHovered) {
        isHovered = false;
        hoverTl.reverse();
      }
    },
    onClick: () => {
      // Pulse click visual feedback
      gsap.to(badgeGroup.scale, {
        x: 0.94,
        y: 0.94,
        duration: 0.08,
        yoyo: true,
        repeat: 1,
        ease: 'power2.inOut'
      });
      // Emit selection event
      ctx.emit('hub-journal.select', { id: config.id });
    }
  });

  // --- 7. APPLY CINEMATIC PRIMITIVES ---
  const activePrimitives = [];
  if (ctx.primitives) {
    if (ctx.primitives['parallax-scroll']) {
      activePrimitives.push(ctx.primitives['parallax-scroll'](badgeGroup, { intensity: 0.4 }));
    }
    if (ctx.primitives['magnetic-cursor']) {
      activePrimitives.push(ctx.primitives['magnetic-cursor'](badgeGroup, { radius: 1.2, strength: 0.35 }));
    }
  }

  // Helper to safely wire up events targeting userData
  function userDataHandlers(target, handlers) {
    target.userData = target.userData || {};
    target.userData.handlers = handlers;
  }

  // --- 8. CLEANUP ---
  root.userData = {
    cleanup() {
      if (animateTimeline) animateTimeline.kill();
      hoverTl.kill();
      bgTexture.dispose();
      capsuleGeom.dispose();
      coreMat.dispose();
      rimMat.dispose();
      activePrimitives.forEach(p => p?.cleanup?.());
    }
  };

  return root;
}
